#!/usr/bin/env bash
# AI generated by: opencode/Muse Spark 1.3
# Prompt: "Create a simple script, that will go through all commits and check, that all usernames and all emails are from the allowlist (i need to make sure that everybody has correctly configured their Github credentials). It will be run as part of future Github CI/CD, target platform is Linux"
# Changes: new script that checks author/committer names and emails of all commits against an allowlist
#
# Checks that every commit's author and committer name/email is on the allowlist.
# Intended for GitHub CI (Linux runner). Fails with exit 1 on violation.
#
# Usage:
#   ./scripts/check-git-credentials.sh [RANGE]
#
#   RANGE defaults to all commits (HEAD). Examples:
#     ./scripts/check-git-credentials.sh            # all commits reachable from HEAD
#     ./scripts/check-git-credentials.sh origin/main..HEAD  # only new commits (pull request)
#
# CI note: checkout must fetch full history, otherwise `git log` sees only
# a truncated range. Use `fetch-depth: 0` in actions/checkout.
set -euo pipefail

# --- Allowlist: edit as team members join/leave ---
ALLOWED_NAMES=(
  "David Alois Bureš"
  "David Daniel Šlapal"
  "Jan Kostka"
  "Lukáš Pollák"
)

ALLOWED_EMAILS=(
  "85311856+DaalbuCZ@users.noreply.github.com"
  "76646834+ddaqua6@users.noreply.github.com"
  "91200807+K0stka@users.noreply.github.com"
  "220401308+lpollak06@users.noreply.github.com"
)
# --- End of allowlist ---

RANGE="${1:-HEAD}"

is_allowed() {
  local value="$1"
  shift
  local allowed
  for allowed in "$@"; do
    if [[ "$value" == "$allowed" ]]; then
      return 0
    fi
  done
  return 1
}

if ! git rev-parse --git-dir >/dev/null 2>&1; then
  echo "error: not inside a git repository" >&2
  exit 2
fi

if ! log_output="$(git log --format='%H%n%an%n%ae%n%cn%n%ce' "$RANGE")"; then
  echo "error: invalid range '$RANGE' (is the repo fully cloned? CI needs fetch-depth: 0)" >&2
  exit 2
fi

# One field per line (sha, author name, author email, committer name,
# committer email). Newlines in names are not supported, but those cannot
# be created via GitHub UI and are vanishingly rare in practice.
total=0
failures=0
while IFS= read -r sha \
  && IFS= read -r author_name \
  && IFS= read -r author_email \
  && IFS= read -r committer_name \
  && IFS= read -r committer_email; do
  total=$((total + 1))
  ok=1
  if ! is_allowed "$author_name" "${ALLOWED_NAMES[@]}"; then
    echo "FAIL $sha: author name '$author_name' is not on the allowlist"
    ok=0
  fi
  if ! is_allowed "$author_email" "${ALLOWED_EMAILS[@]}"; then
    echo "FAIL $sha: author email '$author_email' is not on the allowlist"
    ok=0
  fi
  if ! is_allowed "$committer_name" "${ALLOWED_NAMES[@]}"; then
    echo "FAIL $sha: committer name '$committer_name' is not on the allowlist"
    ok=0
  fi
  if ! is_allowed "$committer_email" "${ALLOWED_EMAILS[@]}"; then
    echo "FAIL $sha: committer email '$committer_email' is not on the allowlist"
    ok=0
  fi
  if [[ "$ok" -eq 0 ]]; then
    failures=$((failures + 1))
  fi
done <<< "$log_output"

if [[ "$total" -eq 0 ]]; then
  echo "No commits found in range '$RANGE'. Nothing to check."
  exit 0
fi

echo "Checked $total commit(s) in range '$RANGE'."

if [[ "$failures" -gt 0 ]]; then
  echo "FAILED: $failures commit(s) with non-allowlisted identity." >&2
  echo "Fix with: git config user.name \"Your Name\" && git config user.email \"you@example.com\"" >&2
  exit 1
fi

echo "OK: all $total commit(s) use allowlisted identities."
